/**
 * Regenerates the two brand assets that must live at stable, un-hashed URLs:
 * public/og-image.jpg and public/wordmark.png.
 *
 * The Open Graph image URL is baked into index.html and cached by every social
 * platform, and 404.html is served by GitHub Pages without the bundle, so
 * neither can use a fingerprinted filename. Both are generated by this script
 * and committed, rather than hand-edited.
 *
 *   node tools/generate-social-image.mjs
 */
import sharp from 'sharp'
import { fileURLToPath } from 'node:url'
import path from 'node:path'

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)))
const WIDTH = 1200
const HEIGHT = 630

const background = await sharp(path.join(root, 'src/assets/hero-1.jpg'))
  .resize(WIDTH, HEIGHT, { fit: 'cover', position: 'centre' })
  .modulate({ brightness: 0.74 })
  .toBuffer()

const wordmark = await sharp(
  path.join(root, 'src/assets/spacelift-logo-transparent.png')
)
  .resize({ width: 620 })
  .toBuffer()

const { height: wordmarkHeight } = await sharp(wordmark).metadata()

const out = path.join(root, 'public/og-image.jpg')

await sharp(background)
  .composite([
    {
      input: wordmark,
      top: Math.round((HEIGHT - wordmarkHeight) / 2) - 20,
      left: Math.round((WIDTH - 620) / 2)
    }
  ])
  .jpeg({ quality: 82, mozjpeg: true })
  .toFile(out)

console.log(`wrote ${path.relative(root, out)}`)

// The standalone 404 page cannot reference content-hashed build output, so it
// needs the wordmark at a stable path too.
const wordmarkOut = path.join(root, 'public/wordmark.png')
await sharp(path.join(root, 'src/assets/spacelift-logo-transparent.png'))
  .resize({ width: 420 })
  .png({ compressionLevel: 9, palette: true })
  .toFile(wordmarkOut)

console.log(`wrote ${path.relative(root, wordmarkOut)}`)
